import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse(`{"title":"Setting up tabs","description":"Assemble the app's bottom navigation bar through the \\"tabs\\" Grid.","frontmatter":{"title":"Setting up tabs","description":"Assemble the app's bottom navigation bar through the \\"tabs\\" Grid."},"headers":[],"relativePath":"en/apptiveteams/tabs.md","filePath":"en/apptiveteams/tabs.md","lastUpdated":1787319236000}`),d={name:"en/apptiveteams/tabs.md"};function r(s,e,n,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="setting-up-tabs" tabindex="-1">Setting up tabs <a class="header-anchor" href="#setting-up-tabs" aria-label="Permalink to &quot;Setting up tabs&quot;">​</a></h1><p>Every row in the Grid with the Key <code>tabs</code> becomes a <strong>tab</strong> in the app&#39;s bottom navigation bar.</p><h2 id="the-fields" tabindex="-1">The fields <a class="header-anchor" href="#the-fields" aria-label="Permalink to &quot;The fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field Key</th><th>Field type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>Text</td><td>yes</td><td>Label of the tab</td></tr><tr><td><code>icon</code></td><td>Files (SVG)</td><td>yes</td><td>Icon for the tab</td></tr><tr><td><code>type</code></td><td>Text / Single Select</td><td>yes</td><td><code>TilesGrid</code>, <code>CardList</code>, or <code>WebView</code></td></tr><tr><td><code>gridUri</code></td><td>Internal Link</td><td>for <code>TilesGrid</code> and <code>CardList</code></td><td>Reference to the Grid holding the content</td></tr><tr><td><code>uri</code></td><td>Weblink</td><td>for <code>WebView</code></td><td>Address shown inside the tab</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Use Single Select instead of free text for <code>type</code></p><p>Set up <code>type</code> as a <strong>Single Select</strong> with exactly these three values. That prevents typos — a tab with the value <code>Tilesgrid</code> instead of <code>TilesGrid</code> is silently skipped.</p></div><h2 id="the-three-tab-types" tabindex="-1">The three tab types <a class="header-anchor" href="#the-three-tab-types" aria-label="Permalink to &quot;The three tab types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Shows</th><th>Needs</th></tr></thead><tbody><tr><td><strong><code>TilesGrid</code></strong></td><td>a grid of tiles</td><td><code>gridUri</code></td></tr><tr><td><strong><code>CardList</code></strong></td><td>a list of cards</td><td><code>gridUri</code></td></tr><tr><td><strong><code>WebView</code></strong></td><td>an embedded web page</td><td><code>uri</code></td></tr></tbody></table><p><code>TilesGrid</code> and <code>CardList</code> pull their content from a linked Grid — one row per tile or card, respectively.</p><p>→ <a href="/en/apptiveteams/kacheln-und-karten">Tiles and cards</a></p><h3 id="webview-tab" tabindex="-1">WebView tab <a class="header-anchor" href="#webview-tab" aria-label="Permalink to &quot;WebView tab&quot;">​</a></h3><p>A tab of type <code>WebView</code> embeds a web page directly inside the app. Instead of a Grid link, you enter the desired address in the <code>uri</code> field — for example your intranet, a shift schedule, or an external portal.</p><div class="warning custom-block"><p class="custom-block-title">Not every page can be embedded</p><p>Some websites block being displayed in embedded views. In that case the tab stays blank. Check every address in the app before rolling the tab out to your workforce.</p></div><h2 id="icons" tabindex="-1">Icons <a class="header-anchor" href="#icons" aria-label="Permalink to &quot;Icons&quot;">​</a></h2><p>Tab icons must be <strong>SVG files</strong>. The app tints them in your primary color — so use <strong>single-color</strong> SVGs without their own fill colors.</p><h2 id="the-navigation-bar-only-appears-with-two-or-more-tabs" tabindex="-1">The navigation bar only appears with two or more tabs <a class="header-anchor" href="#the-navigation-bar-only-appears-with-two-or-more-tabs" aria-label="Permalink to &quot;The navigation bar only appears with two or more tabs&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">A single tab doesn&#39;t get a bar</p><p>The bottom navigation bar is only shown once there are <strong>two valid tabs</strong>. With exactly one tab, its content fills the whole screen — that&#39;s intentional, not a bug.</p></div><h2 id="rows-with-gaps-are-skipped" tabindex="-1">Rows with gaps are skipped <a class="header-anchor" href="#rows-with-gaps-are-skipped" aria-label="Permalink to &quot;Rows with gaps are skipped&quot;">​</a></h2><p>If a row is missing a required field, the app skips it — without any message.</p><div class="tip custom-block"><p class="custom-block-title">Temporarily hiding a tab</p><p>You can use this: clear a row&#39;s title, and the tab disappears from the app without deleting the row and its configuration. To bring it back, enter the title again.</p><p>A cleaner approach is to link a filtered View as the <code>tabs</code> Grid — there you control visibility through a dedicated checkmark field, without clearing data.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptiveteams/kacheln-und-karten">Tiles and cards</a></li><li><a href="/en/apptiveteams/team-space">Setting up the Team Space</a></li><li><a href="/en/apptiveteams/fehlerbehebung">Tips and troubleshooting</a></li></ul>',21)])])}const u=t(d,[["render",r]]);export{b as __pageData,u as default};
